:root {
  --bg: #faf8ef;
  --text: #776e65;
  --board-bg: #bbada0;
  --cell-bg: rgba(238, 228, 218, 0.35);
  --accent: #8f7a66;
}
* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  background: var(--bg);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  min-height: 100vh;
  padding: 20px;
}
.game-wrap {
  width: 100%;
  max-width: 500px;
}
header h1 {
  font-size: 64px;
  line-height: 1;
  color: var(--accent);
}
.subtitle {
  margin-top: 4px;
  font-size: 14px;
  opacity: 0.8;
}
.top-bar {
  display: flex;
  gap: 10px;
  margin: 16px 0;
  align-items: stretch;
  flex-wrap: wrap;
}
.score-box {
  background: var(--board-bg);
  color: white;
  padding: 8px 16px;
  border-radius: 6px;
  text-align: center;
  min-width: 90px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}
.score-box .label {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: #eee4da;
}
.score-box .value {
  font-size: 24px;
  font-weight: bold;
}
.btn {
  background: var(--accent);
  color: white;
  border: none;
  padding: 10px 18px;
  border-radius: 6px;
  font-size: 16px;
  font-weight: bold;
  cursor: pointer;
  transition: transform 0.1s, background 0.2s;
}
.btn:hover { background: #7a6552; }
.btn:active { transform: scale(0.96); }
.btn:focus-visible { outline: 3px solid #edc22e; outline-offset: 2px; }
.board-container {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  background: var(--board-bg);
  border-radius: 8px;
  padding: 10px;
  touch-action: none;
}
.grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  grid-template-rows: repeat(4, 1fr);
  gap: 10px;
  height: 100%;
  width: 100%;
}
.cell {
  background: var(--cell-bg);
  border-radius: 4px;
  display: flex;
  justify-content: center;
  align-items: center;
  font-weight: bold;
  font-size: clamp(20px, 6vw, 40px);
  color: var(--text);
  transition: transform 0.1s ease-out;
}
/* Tile colors */
.cell[data-value="2"] { background: #eee4da; }
.cell[data-value="4"] { background: #ede0c8; }
.cell[data-value="8"] { background: #f2b179; color: white; }
.cell[data-value="16"] { background: #f59563; color: white; }
.cell[data-value="32"] { background: #f67c5f; color: white; }
.cell[data-value="64"] { background: #f65e3b; color: white; }
.cell[data-value="128"] { background: #edcf72; color: white; font-size: clamp(16px, 5vw, 32px); }
.cell[data-value="256"] { background: #edcc61; color: white; font-size: clamp(16px, 5vw, 32px); }
.cell[data-value="512"] { background: #edc850; color: white; font-size: clamp(16px, 5vw, 32px); }
.cell[data-value="1024"] { background: #edc53f; color: white; font-size: clamp(12px, 4vw, 24px); }
.cell[data-value="2048"] { background: #edc22e; color: white; font-size: clamp(12px, 4vw, 24px); }
.cell.pop { animation: pop 0.2s ease-out; }
@keyframes pop {
  0% { transform: scale(0); }
  50% { transform: scale(1.2); }
  100% { transform: scale(1); }
}
.overlay {
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(238, 228, 218, 0.73);
  border-radius: 8px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  z-index: 10;
  opacity: 1;
  transition: opacity 0.3s;
}
.overlay.hidden {
  opacity: 0;
  pointer-events: none;
}
.overlay p {
  font-size: 32px;
  font-weight: bold;
  margin-bottom: 16px;
}
footer {
  margin-top: 16px;
  font-size: 13px;
  opacity: 0.7;
}

