const SIZE = 4;
let board = [];
let score = 0;
let best = 0;
let isGameOver = false;
let hasWon = false;

const gridEl = document.getElementById('grid');
const scoreEl = document.getElementById('score');
const bestEl = document.getElementById('best');
const overlayEl = document.getElementById('overlay');
const overlayTextEl = document.getElementById('overlay-text');
const newGameBtn = document.getElementById('new-game');
const overlayBtn = document.getElementById('overlay-btn');

// --- Storage Helpers ---
function saveState() {
  const state = { board, score, best, isGameOver, hasWon };
  localStorage.setItem('2048_game_state', JSON.stringify(state));
}

function loadState() {
  try {
    const saved = localStorage.getItem('2048_game_state');
    if (!saved) return false;
    const parsed = JSON.parse(saved);
    // Validate shape
    if (Array.isArray(parsed.board) && 
        parsed.board.length === SIZE && 
        typeof parsed.score === 'number' && 
        typeof parsed.best === 'number') {
      board = parsed.board;
      score = parsed.score;
      best = parsed.best;
      isGameOver = !!parsed.isGameOver;
      hasWon = !!parsed.hasWon;
      return true;
    }
  } catch (e) {
    console.error('Failed to parse saved state', e);
  }
  return false;
}

// --- Game Logic ---
function initBoard() {
  board = Array(SIZE).fill(null).map(() => Array(SIZE).fill(0));
  addRandomTile();
  addRandomTile();
  score = 0;
  isGameOver = false;
  hasWon = false;
  hideOverlay();
  render();
  saveState();
}

function addRandomTile() {
  const emptyCells = [];
  for (let r = 0; r < SIZE; r++) {
    for (let c = 0; c < SIZE; c++) {
      if (board[r][c] === 0) emptyCells.push({r, c});
    }
  }
  if (emptyCells.length > 0) {
    const {r, c} = emptyCells[Math.floor(Math.random() * emptyCells.length)];
    board[r][c] = Math.random() < 0.9 ? 2 : 4;
    return true;
  }
  return false;
}

function slide(row) {
  let arr = row.filter(val => val);
  let mergedRow = [];
  let pointsGained = 0;
  for (let i = 0; i < arr.length; i++) {
    if (i < arr.length - 1 && arr[i] === arr[i+1]) {
      const newVal = arr[i] * 2;
      mergedRow.push(newVal);
      pointsGained += newVal;
      i++; // skip next element
    } else {
      mergedRow.push(arr[i]);
    }
  }
  while (mergedRow.length < SIZE) {
    mergedRow.push(0);
  }
  return { newRow: mergedRow, points: pointsGained };
}

function move(direction) {
  if (isGameOver) return;
  let moved = false;
  let gainedPoints = 0;

  if (direction === 'left' || direction === 'right') {
    for (let r = 0; r < SIZE; r++) {
      let row = [...board[r]];
      if (direction === 'right') row.reverse();
      const result = slide(row);
      if (direction === 'right') result.newRow.reverse();
      if (result.newRow.join(',') !== board[r].join(',')) {
        moved = true;
        board[r] = result.newRow;
      }
      gainedPoints += result.points;
    }
  } else {
    for (let c = 0; c < SIZE; c++) {
      let col = [];
      for (let r = 0; r < SIZE; r++) col.push(board[r][c]);
      if (direction === 'down') col.reverse();
      const result = slide(col);
      if (direction === 'down') result.newRow.reverse();
      let colMoved = false;
      for (let r = 0; r < SIZE; r++) {
        if (board[r][c] !== result.newRow[r]) {
          colMoved = true;
          board[r][c] = result.newRow[r];
        }
      }
      if (colMoved) moved = true;
      gainedPoints += result.points;
    }
  }

  if (moved) {
    score += gainedPoints;
    if (score > best) best = score;
    addRandomTile();
    checkWinAndLoss();
    render(true);
    saveState();
  }
}

function checkWinAndLoss() {
  // Check Win
  if (!hasWon) {
    outerLoop:
    for (let r = 0; r < SIZE; r++) {
      for (let c = 0; c < SIZE; c++) {
        if (board[r][c] === 2048) {
          hasWon = true;
          showOverlay('你赢了！继续挑战还是重新开始？', '继续游戏');
          break outerLoop;
        }
      }
    }
  }

  // Check Loss
  if (hasEmptyCell()) return;
  if (canMove()) return;
  isGameOver = true;
  showOverlay('游戏结束', '再来一局');
}

function hasEmptyCell() {
  for (let r = 0; r < SIZE; r++) {
    for (let c = 0; c < SIZE; c++) {
      if (board[r][c] === 0) return true;
    }
  }
  return false;
}

function canMove() {
  for (let r = 0; r < SIZE; r++) {
    for (let c = 0; c < SIZE; c++) {
      const val = board[r][c];
      if (val === 0) return true;
      if (c < SIZE - 1 && board[r][c+1] === val) return true;
      if (r < SIZE - 1 && board[r+1][c] === val) return true;
    }
  }
  return false;
}

// --- Rendering ---
function render(popNewTiles = false) {
  gridEl.innerHTML = '';
  scoreEl.textContent = score;
  bestEl.textContent = best;

  for (let r = 0; r < SIZE; r++) {
    for (let c = 0; c < SIZE; c++) {
      const cell = document.createElement('div');
      cell.className = 'cell';
      const val = board[r][c];
      if (val !== 0) {
        cell.dataset.value = val;
        cell.textContent = val;
        if (popNewTiles) {
          // Simple heuristic: animate all tiles on move
          cell.classList.add('pop');
        }
      }
      gridEl.appendChild(cell);
    }
  }
}

function showOverlay(text, btnText) {
  overlayTextEl.textContent = text;
  overlayBtn.textContent = btnText;
  overlayEl.classList.remove('hidden');
}

function hideOverlay() {
  overlayEl.classList.add('hidden');
}

// --- Event Listeners ---
document.addEventListener('keydown', (e) => {
  if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(e.key)) {
    e.preventDefault();
    switch(e.key) {
      case 'ArrowUp': move('up'); break;
      case 'ArrowDown': move('down'); break;
      case 'ArrowLeft': move('left'); break;
      case 'ArrowRight': move('right'); break;
    }
  }
  // WASD support
  if (['w','a','s','d'].includes(e.key.toLowerCase())) {
    e.preventDefault();
    switch(e.key.toLowerCase()) {
      case 'w': move('up'); break;
      case 's': move('down'); break;
      case 'a': move('left'); break;
      case 'd': move('right'); break;
    }
  }
});

newGameBtn.addEventListener('click', () => {
  initBoard();
});

overlayBtn.addEventListener('click', () => {
  if (isGameOver) {
    initBoard();
  } else {
    hideOverlay();
  }
});

// Touch Support (Basic Swipe)
let touchStartX = 0;
let touchStartY = 0;
const boardContainer = document.querySelector('.board-container');

boardContainer.addEventListener('touchstart', e => {
  touchStartX = e.changedTouches[0].screenX;
  touchStartY = e.changedTouches[0].screenY;
}, {passive: true});

boardContainer.addEventListener('touchend', e => {
  let touchEndX = e.changedTouches[0].screenX;
  let touchEndY = e.changedTouches[0].screenY;
  handleSwipe(touchStartX, touchStartY, touchEndX, touchEndY);
}, {passive: true});

function handleSwipe(startX, startY, endX, endY) {
  let diffX = endX - startX;
  let diffY = endY - startY;
  if (Math.abs(diffX) > Math.abs(diffY)) {
    if (diffX > 0) move('right');
    else move('left');
  } else {
    if (diffY > 0) move('down');
    else move('up');
  }
}

// --- Initialization ---
if (!loadState()) {
  initBoard();
} else {
  render();
  if (isGameOver) {
    showOverlay('游戏结束', '再来一局');
  } else if (hasWon) {
    // If loaded with a win state, keep overlay visible until dismissed or reset
    showOverlay('你赢了！继续挑战还是重新开始？', '继续游戏');
  }
}
